-- Long-format inputs, one row per period and input metric (load from your warehouse).
CREATE TABLE kpi_inputs (period DATE NOT NULL, metric_id VARCHAR NOT NULL, value DOUBLE PRECISION, PRIMARY KEY (period, metric_id));

CREATE VIEW kpi_tree AS
WITH inputs AS (
  SELECT period,
    MAX(CASE WHEN metric_id = 'new_sessions' THEN value END) AS new_sessions,
    MAX(CASE WHEN metric_id = 'add_to_cart_rate' THEN value END) AS add_to_cart_rate,
    MAX(CASE WHEN metric_id = 'checkout_start_rate' THEN value END) AS checkout_start_rate,
    MAX(CASE WHEN metric_id = 'purchase_completion_rate' THEN value END) AS purchase_completion_rate,
    MAX(CASE WHEN metric_id = 'average_order_value' THEN value END) AS average_order_value,
    MAX(CASE WHEN metric_id = 'cost_per_order' THEN value END) AS cost_per_order,
    MAX(CASE WHEN metric_id = 'email_capture_rate' THEN value END) AS email_capture_rate,
    MAX(CASE WHEN metric_id = 'page_load_speed' THEN value END) AS page_load_speed,
    MAX(CASE WHEN metric_id = 'loyalty_membership' THEN value END) AS loyalty_membership,
    MAX(CASE WHEN metric_id = 'returning_sessions' THEN value END) AS returning_sessions,
    MAX(CASE WHEN metric_id = 'product_view_rate' THEN value END) AS product_view_rate,
    MAX(CASE WHEN metric_id = 'customer_ltv' THEN value END) AS customer_ltv
  FROM kpi_inputs
  GROUP BY period
)
, level_1 AS (
  SELECT inputs.*,
    new_sessions + returning_sessions AS sessions,
    product_view_rate * add_to_cart_rate * checkout_start_rate * purchase_completion_rate AS conversion_rate
  FROM inputs
)
, level_2 AS (
  SELECT level_1.*,
    sessions * conversion_rate AS orders
  FROM level_1
)
, level_3 AS (
  SELECT level_2.*,
    orders * average_order_value AS net_revenue,
    orders * cost_per_order AS variable_costs
  FROM level_2
)
, level_4 AS (
  SELECT level_3.*,
    net_revenue - variable_costs AS contribution_profit
  FROM level_3
)
SELECT * FROM level_4;
